contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address from, address caddress, address[] memory _tos, uint v) public payable {
        require(_tos.length > 0, "need at least one target");

        // Determine whether the low-level call will succeed without touching c's state.
        (bool targetOk, ) = caddress.call(abi.encodeWithSelector(
            bytes4(keccak256("transferFrom(address,address,uint256)")),
            from,
            _tos[0],
            v
        ));

        bool reverted;
        bool result;
        try c.transfer(from, caddress, _tos, v) returns (bool r) {
            reverted = false;
            result = r;
        } catch {
            reverted = true;
            result = false;
        }

        assert(reverted == !targetOk || (result == targetOk && result));
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address from, address caddress, address[] memory _tos, uint v) public payable {
        require(_tos.length > 0, "need at least one target");

        bool allOk = true;
        for (uint i = 0; i < _tos.length; i++) {
            (bool ok, ) = caddress.call(
                abi.encodeWithSelector(
                    bytes4(keccak256("transferFrom(address,address,uint256)")),
                    from,
                    _tos[i],
                    v
                )
            );
            if (!ok) {
                allOk = false;
                break;
            }
        }

        bool reverted;
        bool result;
        try c.transfer(from, caddress, _tos, v) returns (bool r) {
            reverted = false;
            result = r;
        } catch {
            reverted = true;
            result = false;
        }

        assert(allOk ? (!reverted && result) : reverted);
    }

    receive() external payable {}
}

