contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address from, address caddress, address[] memory _tos, uint v) public payable {
        require(_tos.length > 0, "need at least one target");

        // Record whether a direct low-level transferFrom call to the first target succeeds.
        bytes4 id = bytes4(keccak256("transferFrom(address,address,uint256)"));
        (bool firstOk,) = caddress.call(abi.encodeWithSelector(id, from, _tos[0], v));

        bool reverted;
        try c.transfer(from, caddress, _tos, v) returns (bool r) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // The rule: c.transfer reverts exactly when the first low-level call would fail
        // (if the first call succeeds, all subsequent calls use the same inputs and target contract);
        // therefore it succeeds otherwise.
        assert(reverted != firstOk);
    }

    receive() external payable {}
}

